const A='assets/', I=A+'images/';
const icons={bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2Z"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',left:'<path d="M20 12H4m6-6-6 6 6 6"/>',play:'<path d="m8 4 12 8-12 8Z"/>',layers:'<path d="m2 8 10-6 10 6-10 6L2 8Zm0 5 10 6 10-6M2 18l10 6 10-6"/>',wind:'<path d="M3 7h12a3 3 0 1 0-3-3M3 12h16a3 3 0 1 1-3 3M3 17h6"/>',shield:'<path d="M12 2 3 6v7c0 5 9 9 9 9s9-4 9-9V6l-9-4Z"/><path d="m8 12 3 3 5-6"/>',wash:'<rect x="3" y="2" width="18" height="20" rx="2"/><circle cx="12" cy="14" r="6"/><path d="M6 5h1m3 0h1m6 0h1M7 14c2-3 6 3 10 0"/>',truck:'<path d="M2 5h13v12H2M15 9h4l3 4v4h-7M2 9H0M2 13H0"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="18" r="3"/>',exchange:'<path d="M21 9A9 9 0 0 0 5 5L2 8m0-5v5h5M3 15a9 9 0 0 0 16 4l3-3m0 5v-5h-5"/>',card:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="M2 9h20"/>',headset:'<path d="M3 14V11a9 9 0 0 1 18 0v3M3 12H1v7h5v-7H3m18 0h2v7h-5v-7h3m0 7c0 3-4 3-7 3"/>',zoom:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6M10 7v6m-3-3h6"/>',needle:'<path d="m4 21 15-18c3-2 4 0 2 3L4 21Zm12-14 2 2"/>'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.layers}</svg>`}
const products={homme:{id:'homme',name:'L’ensemble Bleu Roi',gender:'Homme',color:'Bleu Roi & Blanc',folder:'men-blue',sizeImage:'size-men.png',sizes:['M'],desc:'Le col polo, la coupe cargo et un bleu qui affirme votre style. Votre ensemble complet, du bloc à la ville.',detail:'Un col polo structuré. Des cordons blancs. Des poches cargo à portée de main.',features:['Col chemise à patte boutonnée','Poche poitrine et logo brodé blanc','Pantalon cargo droit et cordon blanc','Fentes latérales pour bouger librement']},femme:{id:'femme',name:'L’ensemble Noir & Rose',gender:'Femme',color:'Noir Onyx & Rose Vif',folder:'women-black-pink',sizeImage:'size-women.png',sizes:['S','M'],desc:'Une silhouette cintrée, un noir essentiel et une touche de rose. La tenue médicale qui vous ressemble.',detail:'Un zip rose signature. Une taille structurée. Un cargo ample pour accompagner vos mouvements.',features:['Col montant et zip rose contrastant','Coupe cintrée et poches basses','Pantalon cargo ample et cordon rose','Broderie Seven et détail rose à la nuque']}};
const stories=[{name:'seven.homme',title:'Du bloc à la ville',image:A+'iphone-raw-selfie-man.png',avatar:A+'iphone-raw-selfie-man.png',product:'homme',slides:[A+'iphone-raw-selfie-man.png',A+'iphone-raw-unbox-man.png',I+'products/men-blue/model-side.png',I+'products/men-blue/model-back.png']},{name:'seven.femme',title:'Votre rythme. Votre style.',image:A+'iphone-raw-selfie-woman.png',avatar:A+'iphone-raw-selfie-woman.png',product:'femme',slides:[A+'iphone-raw-selfie-woman.png',A+'iphone-raw-unbox-woman.png',I+'products/women-black-pink/model-side.png',I+'products/women-black-pink/model-back.png']},{name:'seven.matière',title:'La liberté dans chaque mouvement',image:A+'fabric.png',avatar:I+'products/men-blue/model-front.png',product:'homme',slides:[A+'fabric.png',I+'men/detail-fabric.png'],play:true},{name:'seven.détails',title:'Des détails pensés pour vous',image:A+'iphone-raw-unbox-woman.png',avatar:A+'iphone-raw-selfie-woman.png',product:'femme',slides:[A+'iphone-raw-receiving.png',A+'iphone-raw-unbox-woman.png',I+'products/women-black-pink/details-sheet.png']},{name:'seven.signature',title:'La signature Seven',image:A+'iphone-raw-unbox-man.png',avatar:A+'iphone-raw-selfie-man.png',product:'homme',slides:[A+'iphone-raw-receiving.png',A+'iphone-raw-unbox-man.png',I+'men/detail-chest.png']}];
let page='home',selectedSize='',qty=1,cart=[];try{cart=JSON.parse(localStorage.getItem('seven-cart-v1')||'[]');if(!Array.isArray(cart))cart=[]}catch{}
let storyTimer,storyState,lastFocus;
const img=(p,file='model-front.png')=>I+'products/'+p.folder+'/'+file;
function header(home=false){return `<div class="delivery-banner">${icon('truck')}<span>Livraison partout au Maroc <i>·</i> Paiement à la livraison</span><button data-action="promo">30 MAD offerts ↗</button></div><div class="header-wrap ${home?'home':'inner'}"><header class="container header"><a href="#/" aria-label="Seven — Accueil"><span class="wordmark" aria-label="Seven">Seven<sup>®</sup></span></a><nav class="nav" aria-label="Navigation principale"><a href="#/homme">Homme</a><a href="#/femme">Femme</a><a href="#/marque">La Marque</a></nav><div class="header-actions"><button class="icon-btn" data-action="search" aria-label="Rechercher">${icon('search')}</button><button class="icon-btn support-icon" data-action="contact" aria-label="Contacter Seven">${icon('user')}</button><button class="icon-btn cart-btn" data-action="cart" aria-label="Ouvrir le panier">${icon('bag')}<span class="count">${cart.reduce((n,x)=>n+x.qty,0)}</span></button><button class="icon-btn" data-action="menu" aria-label="Ouvrir le menu">${icon('menu')}</button></div></header></div>`}
function footer(){return `<footer class="footer"><div class="container footer-main"><a href="#/"><span class="wordmark" aria-label="Seven">Seven<sup>®</sup></span></a><nav><a href="#/homme">Homme</a><a href="#/femme">Femme</a><a href="#/marque">La Marque</a><a href="https://wa.me/212698040572" target="_blank" rel="noopener">WhatsApp ↗</a></nav><small>© 2026 Seven. Beyond the Uniform. · Pensé pour les professionnels de santé au Maroc.</small></div></footer>`}
function benefits(){return `<section class="container benefits" id="matiere"><div class="fabric-tile"><img src="${A}fabric.png" alt="Texture du sergé stretch bleu roi" loading="lazy"><div class="fabric-label">${icon('layers')}<div><b>Sergé Lycra Premium</b><small>Souple · Résistant · Respirant</small></div></div></div><div><p class="eyebrow">Pourquoi choisir Seven ?</p><h2>Bien plus qu’une <span class="pinkline">tenue médicale.</span></h2><div class="feature-grid">${[['layers','Confort 4D','Liberté de mouvement toute la journée'],['wind','Respirant','Un tissu agréable au fil des heures'],['shield','Résistant','Pensé pour un usage quotidien'],['wash','Entretien facile','Garde sa tenue, jour après jour']].map(x=>`<div class="feature">${icon(x[0])}<h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></div></section>`}
// Shared Stories component: the same renderer and viewer are used across every page.
function storiesComponent(){return `<section class="stories-section" id="stories"><div class="container"><div class="section-head"><h2>Seven, <span class="pinkline">au quotidien.</span></h2><p>Des silhouettes, des détails et des moments de vie avec Seven. Touchez pour explorer.</p><div class="arrows"><button class="round" data-action="scroll-stories" data-dir="-1" aria-label="Stories précédentes">${icon('left')}</button><button class="round dark" data-action="scroll-stories" data-dir="1" aria-label="Stories suivantes">${icon('arrow')}</button></div></div><div class="stories-track">${stories.map((s,i)=>`<button class="story-card" data-story="${i}" aria-label="Ouvrir la story ${s.name}"><img src="${s.image}" alt="${s.title}" loading="lazy"><div class="story-ticks"><span></span><span></span><span></span><span></span></div><div class="story-header"><img src="${s.avatar}" alt=""><b>${s.name}</b></div>${s.play?`<span class="story-play">${icon('play')}</span>`:''}<span class="story-sticker">${s.title}</span></button>`).join('')}</div><p class="campaign-note">Journal visuel Seven · Images de campagne, dont visuels générés par IA.</p></div></section>`}
function trust(){return `<section class="container trust" aria-label="Les services Seven">${[['truck','Livraison partout au Maroc','Délai confirmé à la commande'],['exchange','Un doute sur la taille ?','Conseil avant de commander'],['card','Paiement à la livraison','Sans carte bancaire'],['headset','Une équipe à votre écoute','Contact direct sur WhatsApp']].map(x=>`<div class="trust-item">${icon(x[0])}<div><b>${x[1]}</b><br>${x[2]}</div></div>`).join('')}</section>`}
function collection(){return `<section class="container collection" id="collection"><div class="section-head"><div><p class="eyebrow">La collection signature</p><h2>Votre prochaine <span class="pinkline">tenue préférée.</span></h2></div><p>Deux silhouettes. Un même esprit.<br>Haut + pantalon cargo, 320 MAD.</p></div><div class="collection-grid">${Object.values(products).map(p=>`<a class="collection-card" href="#/${p.id}"><span class="tag">Collection ${p.gender}</span><div class="image"><img src="${img(p)}" alt="${p.name}" loading="lazy"></div><div class="collection-caption"><div><h3>${p.name}</h3><p>Ensemble complet · 320 MAD</p></div><span class="round dark">${icon('arrow')}</span></div></a>`).join('')}</div></section>`}
function brand(){return `<section class="container brand-section" id="marque"><img src="${I}brand/hero-duo-poster.png" alt="La collection Seven, homme et femme" loading="lazy"><div><p class="eyebrow">Beyond the Uniform</p><h2>Votre métier est exigeant.<br>Votre style vous <span class="pinkline">appartient.</span></h2><p>Seven repense la tenue médicale avec une conviction : vous méritez un vêtement que vous êtes fier de porter.</p><p>Des coupes inspirées du streetwear, des détails soignés et le confort pour suivre votre rythme. De la première consultation à la dernière garde.</p><a class="btn" href="#/homme">Découvrir Seven ${icon('arrow')}</a></div></section>`}
function home(){return `${header(true)}<main><section class="hero"><div class="container"><div class="hero-copy"><p class="eyebrow">Medical Workwear</p><h1>Performance,<br>Confort & Style<br>au Service des<br><span class="pinkline">Professionnels</span></h1><p class="lead">Des tenues médicales modernes, pensées pour votre rythme, du bloc à la ville.</p><div class="hero-buttons"><a href="#collection" class="btn white" data-action="collection">${icon('bag')} Découvrir la Collection ${icon('arrow')}</a><button class="btn outline" data-action="video">${icon('play')} Voir la Vidéo</button></div><div class="hero-social"><div class="avatar-stack"><img src="${A}ugc-man.png" alt=""><img src="${A}ugc-woman.png" alt=""><img src="${I}products/men-blue/model-front.png" alt=""></div><span>Pensé pour celles et ceux<br>qui prennent soin des autres.</span></div></div></div></section>${benefits()}${storiesComponent()}${trust()}${collection()}${brand()}</main>${footer()}`}
function productProof(p){const woman=p.id==='femme';const cards=[{image:A+'iphone-raw-receiving.png',title:'Le moment de la réception',text:'POV : votre colis Seven arrive.'},{image:A+(woman?'iphone-raw-unbox-woman.png':'iphone-raw-unbox-man.png'),title:'On ouvre le colis',text:woman?'Noir & Rose, au premier regard.':'Le Bleu Roi, à peine déballé.'},{image:A+(woman?'iphone-raw-selfie-woman.png':'iphone-raw-selfie-man.png'),title:'Le premier essayage',text:'Un aperçu à la maison, sans mise en scène studio.'},{image:A+'iphone-raw-details.png',title:'Les détails, de près',text:'Couleurs, broderies et matière en lumière naturelle.'}];return `<section class="product-proof" aria-label="Seven en situation"><div class="proof-heading"><b>Votre Seven, en situation</b><div><button class="proof-arrow" data-proof-dir="-1" aria-label="Visuel précédent">${icon('left')}</button><button class="proof-arrow" data-proof-dir="1" aria-label="Visuel suivant">${icon('arrow')}</button></div></div><div class="proof-carousel">${cards.map(c=>`<article class="proof-card"><button data-lightbox="${c.image}" aria-label="Agrandir : ${c.title}"><img src="${c.image}" alt="${c.title}" loading="lazy"></button><div><b>${c.title}</b><p>${c.text}</p></div></article>`).join('')}</div><p class="proof-disclosure">Visuels de campagne générés par IA · Style iPhone raw · Packaging illustratif.</p><div class="review-preview-note">Aperçu du module avis · Exemples à remplacer par des retours clients authentiques.</div><div class="proof-carousel review-carousel">${cards.map((c,i)=>`<article class="review-draft"><img src="${c.image}" alt="Visuel de campagne, pas un portrait client"><div><span>Exemple d’avis · Non publié par un client</span><p dir="auto">« ${['La coupe est confortable et les détails sont bien pensés.','الثوب خفيف والقَصّة زوينة، نقدر نتحرك فيه براحة.','Franchement زوين، la coupe mzyana et les poches pratiques.','L’ensemble جا مزيان، surtout les finitions et la couleur.'][i]} »</p><small>Maquette · Texte et photo de campagne</small></div></article>`).join('')}</div></section>`}
function profileTriggers(){const picks=page==='femme'?[1,3,2]:[0,4,2];return `<section class="product-stories" aria-label="Seven en mouvement"><div class="product-stories-heading"><h3>Seven en mouvement</h3><p>Touchez une story pour découvrir la tenue.</p></div><div class="product-stories-grid">${picks.map(i=>{const s=stories[i];return `<button class="product-story" data-story="${i}" aria-label="Voir la story ${s.name}"><img class="product-story-image" src="${s.image}" alt="${s.title}" loading="lazy"><span class="product-story-ticks"><i></i><i></i><i></i></span><span class="product-story-profile"><img src="${s.avatar}" alt=""><span>${s.name}</span></span><span class="product-story-play">${icon('play')}</span><span class="product-story-caption">${s.title}<small>Voir la story ↗</small></span></button>`}).join('')}</div></section>`}

function product(p){const files=['model-front.png','packshot-front.png','model-side.png','model-back.png','details-sheet.png'];return `${header()}<main class="product-page"><div class="container"><section class="product-hero" id="choisir"><div class="gallery"><div class="gallery-main"><button data-action="zoom" aria-label="Agrandir la photo produit"><img id="main-product-image" src="${img(p)}" alt="${p.name}, vue face"></button><div class="gallery-badge">LA TENUE SIGNATURE<strong>Haut + Cargo</strong>Ensemble complet</div><span class="zoom-badge">${icon('zoom')}</span></div><div class="thumbs">${files.map((f,i)=>`<button class="thumb ${i===0?'active':''}" data-image="${img(p,f)}" aria-label="${['Vue face','Ensemble seul','Vue de profil','Vue de dos','Détails du produit'][i]}"><img src="${img(p,f)}" alt="" loading="lazy"></button>`).join('')}</div><p class="campaign-note">Visuels de collection Seven · Cliquez pour explorer les détails.</p></div><div class="product-info"><span class="tag">Seven Signature · ${p.gender}</span><h1>${p.name}<br><span class="muted">Du bloc à la ville.</span></h1><p class="lead">${p.desc}</p><div class="product-feature-row"><div>${icon('wind')}Respirant<br><b>Léger au quotidien</b></div><div>${icon('layers')}Stretch<br><b>Liberté de mouvement</b></div><div>${icon('bag')}Pratique<br><b>Poches cargo</b></div></div><p class="field-label">Choisissez votre silhouette</p><div class="options">${Object.values(products).map(o=>`<a href="#/${o.id}" class="offer ${o.id===p.id?'selected':''}"><span class="radio"></span><img src="${img(o)}" alt=""><span><strong>${o.gender} · ${o.color}</strong><small>Haut + pantalon cargo</small></span><span class="offer-price">320 MAD</span></a>`).join('')}</div><div class="field-label">Votre taille<button class="text-btn" data-action="sizes">Guide des tailles ↗</button></div><div class="sizes">${p.sizes.map(s=>`<button class="size ${s===selectedSize?'active':''}" data-size="${s}" aria-pressed="${s===selectedSize}">${s}</button>`).join('')}</div><p class="availability">${p.gender==='Homme'?'M standard':'S et M'} · Disponibilité à confirmer avec Seven.</p><div class="price-row"><div class="offer-price-stack"><span class="regular-price">350 MAD</span><span class="price">320 MAD</span><span class="saving-label">Vous économisez 30 MAD</span></div><small>Le prix de l’ensemble<br>Haut + pantalon inclus</small></div>${productProof(p)}<div class="buy-row"><div class="quantity"><button data-action="qty-minus" aria-label="Diminuer la quantité">−</button><b class="qty-value">${qty}</b><button data-action="qty-plus" aria-label="Augmenter la quantité">+</button></div><button class="btn wide" data-action="buy">Commander mon ensemble ${icon('arrow')}</button></div><div class="mini-trust"><span>${icon('truck')} Partout au Maroc</span><span>${icon('card')} Paiement à la livraison</span></div>${profileTriggers()}<button class="personalisation" data-action="personalisation">${icon('needle')}<span><b>Votre équipe. Votre signature.</b><small>Broderie et commandes groupées · Parlons de votre projet ↗</small></span></button><div class="objection-accordions">${[['Ce qui rend cet ensemble différent',p.detail+' Mélange coton, polyester et élasthanne : douceur, tenue et liberté de mouvement.'],['Est-ce confortable pour une longue journée ?','Le tissu stretch suit les mouvements, les fentes latérales apportent de l’aisance et la ceinture élastiquée se règle avec un cordon. Une coupe pensée pour accompagner votre rythme.'],['Et si j’hésite entre deux tailles ?','Consultez le guide des tailles puis demandez conseil à Seven sur WhatsApp. Nous confirmons les mesures et la disponibilité avant de valider votre demande.'],['Qu’est-ce que je reçois pour 320 MAD ?','Un ensemble assorti complet : le haut et le pantalon cargo. Le prix régulier est de 350 MAD ; l’offre de 30 MAD est déjà appliquée. Les frais de livraison sont confirmés séparément.'],['Comment être sûr avant de commander ?','Vous préparez votre demande sans paiement en ligne. Seven confirme avec vous la taille, la disponibilité, les frais et le délai de livraison sur WhatsApp. Le paiement s’effectue à la livraison.']].map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></div></section></div>${trust()}<section class="container product-detail"><div><p class="eyebrow">Chaque détail compte</p><h2>Conçu pour la performance.<br>Pensé pour <span class="pinkline">vous.</span></h2><p class="muted">Une tenue qui accompagne vos gestes, votre rythme et votre personnalité.</p><ul class="check-list">${p.features.map(t=>`<li>${t}</li>`).join('')}</ul><a href="#choisir" class="btn outline">Choisir mon ensemble ${icon('arrow')}</a></div><div class="detail-media"><img src="${img(p,'model-side.png')}" alt="Coupe et profil de ${p.name}" loading="lazy"><div class="detail-strip">${['packshot-front.png','model-back.png','details-sheet.png'].map(f=>`<button data-lightbox="${img(p,f)}" class="thumb" aria-label="Explorer les détails"><img src="${img(p,f)}" alt="Détail ${p.gender}" loading="lazy"></button>`).join('')}</div></div></section><section class="container product-detail reverse"><div><p class="eyebrow">La qualité que vous ressentez</p><h2>Souple par nature.<br>Résistant par <span class="pinkline">conception.</span></h2><p class="muted">Le mélange coton, polyester et élasthanne apporte douceur au contact de la peau, tenue de la forme et liberté de mouvement.</p><div class="specs">${[['Coton','Douceur et respirabilité'],['Polyester','Résistance et séchage rapide'],['Élasthanne','Souplesse et liberté de mouvement'],['Finitions Seven','Broderie, poches et cordons signature']].map(s=>`<div><h3>${s[0]}</h3><p>${s[1]}</p></div>`).join('')}</div></div><div class="detail-media"><img src="${A}fabric.png" alt="Texture du sergé stretch Seven" loading="lazy"></div></section>${howto(p)}${storiesComponent()}${collection()}${faq()}<section class="container final-cta"><p class="eyebrow">Votre prochaine garde, autrement.</p><h2>Prêt à passer <span class="pinkline">chez Seven ?</span></h2><p>Votre ensemble complet à 320 MAD. Paiement à la livraison au Maroc.</p><button class="btn" data-action="buy">Commander mon ensemble ${icon('arrow')}</button></section></main>${footer()}<aside class="sticky"><div class="container"><div class="sticky-product"><img src="${img(p)}" alt=""><div><b>${p.name}</b><small>Taille <span class="sticky-size">${selectedSize}</span> · Haut + cargo</small></div></div><span class="sticky-price"><del class="sticky-regular">${350*qty} MAD</del><span class="sticky-total">${320*qty}</span> MAD</span><button class="btn" data-action="buy">Commander ${icon('arrow')}</button></div></aside>`}
function howto(p){return `<section class="howto"><div class="container"><p class="eyebrow">Simple, du début à la fin</p><h2>Votre Seven en <span class="pinkline">3 étapes.</span></h2><div class="steps">${[['Choisissez votre ensemble','Sélectionnez votre silhouette et consultez le guide pour choisir votre taille.',img(p,'packshot-front.png')],['Préparez votre commande','Renseignez vos coordonnées et envoyez votre demande à Seven sur WhatsApp.',img(p,'model-front.png')],['Recevez votre Seven','Notre équipe confirme la disponibilité, les frais et le délai. Vous payez à la livraison.',img(p,'model-side.png')]].map((x,i)=>`<article class="step"><span class="number">${i+1}</span><img src="${x[2]}" alt="${x[0]}" loading="lazy"><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></div></section>`}
function faq(){return `<section class="container"><div class="faq-section" id="faq"><p class="eyebrow" style="text-align:center">On répond à vos questions</p><h2>Avant votre première garde.</h2>${[['Quelle taille choisir ?','Le dossier de collection indique M pour Homme, S et M pour Femme. Consultez le guide et contactez Seven pour confirmer les mesures et la disponibilité avant commande.'],['Que comprend le prix de 320 MAD ?','Un ensemble complet : le haut et le pantalon cargo assorti. Les éventuels frais de livraison sont confirmés par Seven avant validation.'],['Comment entretenir ma tenue ?','Suivez les indications de l’étiquette du vêtement. Notre équipe peut vous préciser les consignes adaptées au tissu avant votre commande.'],['Comment se passe la livraison ?','Seven livre au Maroc. La disponibilité, le délai et les frais sont confirmés directement par notre équipe sur WhatsApp.'],['Comment payer ma commande ?','Le paiement s’effectue à la livraison. La demande envoyée sur WhatsApp permet à Seven de confirmer les détails avec vous.'],['Puis-je échanger ma taille ?','Contactez Seven sur WhatsApp pour connaître les conditions d’échange et être accompagné dans le choix de votre taille.'],['Une commande pour mon équipe ?','Contactez-nous pour les commandes groupées et les possibilités de personnalisation. Les conditions sont établies avec Seven selon votre projet.']].map((x,i)=>`<details ${i===0?'open':''}><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></section>`}
function render(){closeOverlay(false);const route=(location.hash.replace('#/','').split('?')[0]||'home');page=products[route]?route:route==='marque'?'marque':'home';qty=1;selectedSize=products[page]?.sizes[0]||'';document.body.className=products[page]?'product-page':'';$('#app').innerHTML=products[page]?product(products[page]):page==='marque'?`${header()}<main>${brand()}${benefits()}${storiesComponent()}${collection()}</main>${footer()}`:home();document.title=products[page]?`Seven — ${products[page].name} · 320 MAD`:'Seven — Beyond the Uniform';window.scrollTo(0,0)}
function closeOverlay(focus=true){clearTimeout(storyTimer);const root=$('#overlay-root');root.innerHTML='';document.body.classList.remove('locked');if(focus&&lastFocus?.isConnected)lastFocus.focus()}
function overlay(content,cls=''){lastFocus=document.activeElement;clearTimeout(storyTimer);$('#overlay-root').innerHTML=`<div class="overlay ${cls}" data-overlay>${content}</div>`;document.body.classList.add('locked');setTimeout(()=>$('#overlay-root button, #overlay-root input, #overlay-root a')?.focus(),0)}
function modal(title,content){overlay(`<section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Fermer">×</button></div>${content}</section>`)}
function saveCart(){localStorage.setItem('seven-cart-v1',JSON.stringify(cart));$$('.count').forEach(x=>x.textContent=cart.reduce((n,i)=>n+i.qty,0))}
function addToCart(){const p=products[page];if(!p)return;let item=cart.find(x=>x.id===p.id&&x.size===selectedSize);if(item)item.qty+=qty;else cart.push({id:p.id,size:selectedSize,qty});saveCart();openCheckout(1)}
function openCheckout(step=1){const total=cart.reduce((n,i)=>n+320*i.qty,0);overlay(`<section class="drawer" role="dialog" aria-modal="true" aria-label="Votre commande"><div class="modal-head"><h2>${step===1?'Votre ensemble Seven':'Vos coordonnées'}</h2><button class="close" data-action="close" aria-label="Fermer">×</button></div>${!cart.length?`<div class="empty">${icon('bag')}<p>Votre panier attend votre premier Seven.</p><a href="#/homme" class="btn">Découvrir la collection</a></div>`:`<div class="checkout-steps"><b>1</b> Votre ensemble <span></span><b>${step===2?'2':'○'}</b> Vos coordonnées</div>${cart.map((item,i)=>{let p=products[item.id];return `<div class="checkout-summary"><img src="${img(p)}" alt="${p.name}"><div><strong>${p.name}</strong><p>Taille ${item.size} · ${item.qty} ensemble${item.qty>1?'s':''}</p><b>${320*item.qty} MAD</b>${step===1?`<p><button class="text-btn" data-remove="${i}">Retirer</button></p>`:''}</div></div>`}).join('')}${step===1?`<p class="muted" style="font-size:13px">Votre ensemble comprend le haut et le pantalon cargo. La disponibilité et la livraison sont confirmées par Seven.</p><div class="checkout-bottom"><div class="discount-recap">Offre Seven appliquée · −${cart.reduce((n,i)=>n+i.qty*30,0)} MAD</div><div class="total-row"><span>Sous-total</span><b>${total} MAD</b></div><button class="btn wide" data-action="checkout-next">Continuer ${icon('arrow')}</button><small>${icon('card')} Paiement à la livraison · Frais de livraison à confirmer.</small></div>`:`<form id="checkout-form" class="form-grid"><label>Nom complet<input name="name" autocomplete="name" required minlength="2" placeholder="Votre nom et prénom"></label><label>Téléphone<input name="phone" type="tel" autocomplete="tel" required pattern="[+0-9 ()-]{9,18}" placeholder="06 00 00 00 00"></label><label>Ville<input name="city" autocomplete="address-level2" required placeholder="Casablanca, Rabat…"></label><label>Adresse de livraison<textarea name="address" autocomplete="street-address" rows="2" required placeholder="Quartier, rue, immeuble…"></textarea></label><label>Une précision ? (facultatif)<input name="note" maxlength="250" placeholder="Disponibilité, question sur la taille…"></label><div class="checkout-bottom"><div class="discount-recap">Offre Seven appliquée · −${cart.reduce((n,i)=>n+i.qty*30,0)} MAD</div><div class="total-row"><span>Sous-total</span><b>${total} MAD</b></div><p class="order-error" id="order-error"></p><button class="btn wide" type="submit">Envoyer sur WhatsApp ${icon('arrow')}</button><button class="text-btn" type="button" data-action="checkout-back" style="margin-top:20px">← Retour à ma sélection</button><small>WhatsApp s’ouvre avec votre demande préremplie. Envoyez-la pour que Seven confirme la disponibilité, la livraison et le montant final. Vos coordonnées sont transmises à Seven uniquement à cet envoi.</small></div></form>`}`}</section>`,'drawer-overlay')}
function openStory(index,slide=0){clearTimeout(storyTimer);if(index>=stories.length){closeOverlay();return}if(index<0)index=stories.length-1;const s=stories[index];if(slide>=s.slides.length){openStory(index+1,0);return}if(slide<0){index=(index-1+stories.length)%stories.length;slide=stories[index].slides.length-1;return openStory(index,slide)}storyState={index,slide,paused:false};overlay(`<section class="story-viewer" role="dialog" aria-modal="true" aria-label="Story ${s.name}"><img class="story-image" src="${s.slides[slide]}" alt="${s.title}"><div class="story-progress">${s.slides.map((_,i)=>`<span class="${i<slide?'done':i===slide?'current':''}"><i></i></span>`).join('')}</div><div class="story-header"><img src="${s.avatar}" alt=""><b>${s.name}</b> · Seven</div><button class="story-pause" data-action="pause-story" aria-label="Mettre en pause">Ⅱ</button><button class="close story-close" data-action="close" aria-label="Fermer les stories">×</button><button class="story-nav prev" data-action="story-prev" aria-label="Story précédente"></button><button class="story-nav next" data-action="story-next" aria-label="Story suivante"></button><span class="story-sticker">${s.title}</span><a class="btn white story-shop" href="#/${s.product}" data-action="story-shop">Découvrir l’ensemble · 320 MAD ${icon('arrow')}</a></section>`,'story-overlay');storyTimer=setTimeout(()=>openStory(index,slide+1),6000)}
function lightbox(src){overlay(`<section class="lightbox" role="dialog" aria-modal="true" aria-label="Photo agrandie"><button class="close" data-action="close" aria-label="Fermer">×</button><img src="${src}" alt="Détail Seven agrandi"></section>`)}
function updateQty(){ $$('.qty-value').forEach(x=>x.textContent=qty);$$('.sticky-total').forEach(x=>x.textContent=320*qty);$$('.sticky-regular').forEach(x=>x.textContent=350*qty+' MAD')}
document.addEventListener('click',e=>{const anchor=e.target.closest('a[href^="#"]');if(anchor&&!anchor.getAttribute('href').startsWith('#/')){const target=document.getElementById(anchor.hash.slice(1));if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth'});return}}const story=e.target.closest('[data-story]');if(story){openStory(Number(story.dataset.story));return}const thumb=e.target.closest('[data-image]');if(thumb){$('#main-product-image').src=thumb.dataset.image;$('#main-product-image').alt=thumb.getAttribute('aria-label');$$('.thumbs .thumb').forEach(x=>x.classList.toggle('active',x===thumb));return}const zoom=e.target.closest('[data-lightbox]');if(zoom){lightbox(zoom.dataset.lightbox);return}const size=e.target.closest('[data-size]');if(size){selectedSize=size.dataset.size;$$('.size').forEach(x=>{x.classList.toggle('active',x===size);x.setAttribute('aria-pressed',String(x===size))});$$('.sticky-size').forEach(x=>x.textContent=selectedSize);return}const remove=e.target.closest('[data-remove]');if(remove){cart.splice(Number(remove.dataset.remove),1);saveCart();openCheckout();return}if(e.target.matches('[data-overlay]')){closeOverlay();return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;switch(a){case'close':closeOverlay();break;case'promo':openPromo();break;case'collection':e.preventDefault();$('#collection').scrollIntoView({behavior:'smooth'});break;case'video':overlay(`<section class="modal video-modal" role="dialog" aria-modal="true" aria-label="Le film Seven"><button class="close" data-action="close" aria-label="Fermer">×</button><video controls autoplay playsinline src="${A}campaign.mp4"></video></section>`);break;case'scroll-stories':b.closest('.stories-section').querySelector('.stories-track').scrollBy({left:Number(b.dataset.dir)*400,behavior:'smooth'});break;case'buy':addToCart();break;case'cart':openCheckout();break;case'checkout-next':openCheckout(2);break;case'checkout-back':openCheckout(1);break;case'qty-minus':qty=Math.max(1,qty-1);updateQty();break;case'qty-plus':qty=Math.min(20,qty+1);updateQty();break;case'zoom':lightbox($('#main-product-image').src);break;case'sizes':modal('Le bon fit, pour vous.',`<p class="muted" style="font-size:13px">Guide ${products[page].gender} · Les mesures et disponibilités sont à confirmer avec Seven avant commande.</p><img class="size-image" src="${A+products[page].sizeImage}" alt="Guide des tailles ${products[page].gender}"><a class="btn wide" href="https://wa.me/212698040572?text=${encodeURIComponent('Bonjour Seven, pouvez-vous m’aider à choisir ma taille pour le modèle '+products[page].gender+' ?')}" target="_blank" rel="noopener">Un conseil sur ma taille ↗</a>`);break;case'menu':modal('Explorez Seven',`<nav class="menu-links"><a href="#/">Accueil ↗</a><a href="#/homme">Homme ↗</a><a href="#/femme">Femme ↗</a><a href="#/marque">La Marque ↗</a><a href="https://wa.me/212698040572" target="_blank" rel="noopener">Contacter Seven ↗</a></nav>`);break;case'personalisation':modal('Votre équipe, en Seven.',`<p class="muted">Couleurs de votre établissement, nom ou logo brodé, ensembles pour une promotion : Seven étudie votre projet avec vous.</p><p class="muted">Options, quantités et tarifs sur devis après confirmation par notre équipe.</p><a class="btn wide" href="https://wa.me/212698040572?text=Bonjour%20Seven%2C%20je%20souhaite%20parler%20d%E2%80%99une%20commande%20group%C3%A9e%20et%20de%20personnalisation." target="_blank" rel="noopener">Discuter de mon projet ↗</a>`);break;case'contact':modal('À votre écoute.',`<p class="muted">Une question sur la taille, la livraison ou une commande pour votre équipe ? Échangez directement avec Seven.</p><a class="btn wide" href="https://wa.me/212698040572" target="_blank" rel="noopener">Contacter sur WhatsApp ↗</a>`);break;case'search':modal('Trouvez votre Seven',`<input type="search" id="search" class="search-input" placeholder="Homme, femme, bleu, noir…" aria-label="Rechercher dans la collection"><div class="search-results" id="search-results"></div>`);searchResults('');$('#search').focus();break;case'story-next':openStory(storyState.index,storyState.slide+1);break;case'story-prev':openStory(storyState.index,storyState.slide-1);break;case'pause-story':storyState.paused=!storyState.paused;$('.story-viewer').classList.toggle('paused',storyState.paused);b.textContent=storyState.paused?'▷':'Ⅱ';b.setAttribute('aria-label',storyState.paused?'Reprendre':'Mettre en pause');clearTimeout(storyTimer);if(!storyState.paused)storyTimer=setTimeout(()=>openStory(storyState.index,storyState.slide+1),6000);break;case'story-shop':closeOverlay();break;}});
function searchResults(query){const q=query.toLocaleLowerCase('fr');const found=Object.values(products).filter(p=>(p.name+' '+p.gender+' '+p.color).toLocaleLowerCase('fr').includes(q));$('#search-results').innerHTML=found.map(p=>`<a class="search-result" href="#/${p.id}"><img src="${img(p)}" alt="${p.name}"><p><b>${p.name}</b><br>${p.gender} · 320 MAD</p>${icon('arrow')}</a>`).join('')||'<p class="muted">Aucun résultat. Essayez « bleu » ou « femme ».</p>'}
document.addEventListener('input',e=>{if(e.target.id==='search')searchResults(e.target.value)});
document.addEventListener('submit',e=>{if(e.target.id!=='checkout-form')return;e.preventDefault();const d=new FormData(e.target);const order=cart.map(x=>`${products[x.id].name} — Taille ${x.size} — Qté ${x.qty} — ${x.qty*320} MAD`).join('\n');const text=`Bonjour Seven, je souhaite commander :\n\n${order}\n\nSous-total : ${cart.reduce((n,x)=>n+x.qty*320,0)} MAD (livraison à confirmer)\n\nNom : ${d.get('name')}\nTéléphone : ${d.get('phone')}\nVille : ${d.get('city')}\nAdresse : ${d.get('address')}\nNote : ${d.get('note')||'—'}\n\nMerci de confirmer les tailles disponibles, les frais et le délai de livraison. Paiement à la livraison.`;window.open('https://wa.me/212698040572?text='+encodeURIComponent(text),'_blank','noopener');$('#order-error').textContent='Votre demande est prête dans WhatsApp. Envoyez le message à Seven pour la confirmer.';});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeOverlay();if($('.story-viewer')){if(e.key==='ArrowRight')openStory(storyState.index,storyState.slide+1);if(e.key==='ArrowLeft')openStory(storyState.index,storyState.slide-1)}const root=$('#overlay-root');if(e.key==='Tab'&&root.children.length){const f=$$('button:not([disabled]),a[href],input,textarea,select',root);if(!f.length)return;const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(a&&a.hash===location.hash)closeOverlay()});
window.addEventListener('hashchange',render);render();

let promoRole='',promoProduct='';
function openPromo(step=1){try{sessionStorage.setItem('seven-offer-seen','1')}catch{}if(step===1){promoRole='';promoProduct=''}
const content=step===1?`<span class="tag">Offre Seven</span><div class="promo-amount">−30 <span>MAD</span></div><h2>Votre prochain Seven,<br>avec 30 MAD de moins.</h2><p>Votre ensemble complet à <b>320 MAD</b> au lieu de <del>350 MAD</del>. Le haut + le pantalon cargo, dans votre style.</p><p class="promo-label">Vous êtes…</p><div class="promo-choices">${['Médecin','Infirmier(ère)','Étudiant(e)','Autre'].map(r=>`<button class="promo-chip" data-promo-role="${r}">${r}</button>`).join('')}</div><small class="promo-note">Offre déjà incluse dans les prix affichés. Frais de livraison confirmés par Seven.</small>`:step===2?`<span class="tag">Votre silhouette · Étape 2/3</span><h2>Quel Seven<br>vous ressemble ?</h2><div class="promo-products">${Object.values(products).map(p=>`<button data-promo-product="${p.id}"><img src="${img(p)}" alt="${p.name}"><b>${p.gender}</b><span>${p.color}</span><strong>320 MAD <del>350 MAD</del></strong></button>`).join('')}</div>`:`<span class="tag">Votre demande · Étape 3/3</span><h2>On prépare votre Seven ?</h2><p>${products[promoProduct].name} · <b>320 MAD</b> au lieu de 350 MAD.</p><form id="promo-form" class="form-grid"><label>Votre prénom<input name="name" autocomplete="given-name" placeholder="Votre prénom" required></label><label>Votre téléphone<input name="phone" type="tel" autocomplete="tel" placeholder="06 00 00 00 00" required pattern="[+0-9 ()-]{9,18}"></label><label>Une broderie pour votre équipe ? (facultatif)<input name="embroidery" maxlength="80" placeholder="Nom, logo, projet…"></label><button class="btn wide" type="submit">Demander mon offre sur WhatsApp ${icon('arrow')}</button><small class="promo-note">Envoyez le message dans WhatsApp pour transmettre votre demande à Seven. Taille, disponibilité et livraison à confirmer. Personnalisation sur devis.</small></form>`;
overlay(`<section class="modal promo-modal" role="dialog" aria-modal="true" aria-label="Offre Seven"><button class="close promo-close" data-action="close" aria-label="Fermer l’offre">×</button><div class="promo-photo"><img src="${A}hero.png" alt="La collection Seven"></div><div class="promo-content">${content}</div></section>`)}
document.addEventListener('click',e=>{const r=e.target.closest('[data-promo-role]');if(r){promoRole=r.dataset.promoRole;openPromo(2)}const p=e.target.closest('[data-promo-product]');if(p){promoProduct=p.dataset.promoProduct;openPromo(3)}});
document.addEventListener('submit',e=>{if(e.target.id!=='promo-form')return;e.preventDefault();const d=new FormData(e.target);const text=`Bonjour Seven, je souhaite profiter de l’offre de 30 MAD : ${products[promoProduct].name} à 320 MAD au lieu de 350 MAD.\nProfil : ${promoRole}\nPrénom : ${d.get('name')}\nTéléphone : ${d.get('phone')}\nPersonnalisation : ${d.get('embroidery')||'Sans demande'}\nMerci de confirmer les tailles disponibles et les modalités de livraison.`;window.open('https://wa.me/212698040572?text='+encodeURIComponent(text),'_blank','noopener');});
setTimeout(()=>{let seen=false;try{seen=sessionStorage.getItem('seven-offer-seen')==='1'}catch{}if(!seen&&!$('#overlay-root').children.length)openPromo()},8000);

document.addEventListener('click',e=>{const b=e.target.closest('[data-proof-dir]');if(b)b.closest('.product-proof').querySelector('.proof-carousel').scrollBy({left:Number(b.dataset.proofDir)*230,behavior:'smooth'})});
